import { TrendingDown, TrendingUp, Minus } from "lucide-react";
import { StatsSummary } from "@/store/weightStore";

interface SummaryCardsProps {
  summary: StatsSummary | null;
}

export default function SummaryCards({ summary }: SummaryCardsProps) {
  if (!summary) {
    return (
      <div className="grid grid-cols-2 gap-3">
        {[1, 2, 3, 4].map((i) => (
          <div key={i} className="p-4 bg-white rounded-2xl shadow-card h-24 animate-pulse" />
        ))}
      </div>
    );
  }

  const isPositive = summary.change > 0;
  const isZero = summary.change === 0;
  const TrendIcon = isZero ? Minus : isPositive ? TrendingUp : TrendingDown;

  const cards = [
    { label: "平均体重", value: summary.average.toFixed(1), unit: "kg" },
    { label: "最高体重", value: summary.max.toFixed(1), unit: "kg" },
    { label: "最低体重", value: summary.min.toFixed(1), unit: "kg" },
    {
      label: "变化",
      value: `${isPositive ? "+" : ""}${summary.change.toFixed(1)}`,
      unit: "kg",
      icon: <TrendIcon size={14} className={isPositive ? "text-red-500" : "text-green-600"} />,
      valueColor: isPositive ? "text-red-500" : isZero ? "text-moss" : "text-green-600",
    },
  ];

  return (
    <div className="grid grid-cols-2 gap-3 animate-slideUp">
      {cards.map((card) => (
        <div
          key={card.label}
          className="flex flex-col gap-1 p-4 bg-white rounded-2xl shadow-card"
        >
          <span className="text-xs text-moss font-medium flex items-center gap-1">
            {card.label}
            {card.icon}
          </span>
          <div className="flex items-baseline gap-1">
            <span className={`text-2xl font-display font-bold ${card.valueColor || "text-olive"}`}>
              {card.value}
            </span>
            <span className="text-xs text-moss font-medium">{card.unit}</span>
          </div>
        </div>
      ))}
    </div>
  );
}
