import { Delete } from "lucide-react";

interface NumericKeypadProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: () => void;
  disabled?: boolean;
}

export default function NumericKeypad({
  value,
  onChange,
  onSubmit,
  disabled,
}: NumericKeypadProps) {
  const keys = ["1", "2", "3", "4", "5", "6", "7", "8", "9", ".", "0", "backspace"];

  function handlePress(key: string) {
    if (disabled) return;

    if (key === "backspace") {
      onChange(value.slice(0, -1));
      return;
    }

    if (key === ".") {
      if (value.includes(".")) return;
      onChange(value + key);
      return;
    }

    if (value.replace(".", "").length >= 4) return;
    onChange(value + key);
  }

  const canSubmit = value.length > 0 && parseFloat(value) > 0;

  return (
    <div className="flex flex-col gap-3">
      <div className="grid grid-cols-3 gap-3">
        {keys.map((key) => (
          <button
            key={key}
            type="button"
            onClick={() => handlePress(key)}
            disabled={disabled}
            className="h-14 rounded-2xl bg-white shadow-card text-olive text-xl font-semibold active:scale-95 transition-transform disabled:opacity-40 flex items-center justify-center"
          >
            {key === "backspace" ? <Delete size={22} /> : key}
          </button>
        ))}
      </div>
      <button
        type="button"
        onClick={onSubmit}
        disabled={!canSubmit || disabled}
        className="w-full h-14 rounded-2xl bg-tangerine text-white font-display text-lg font-semibold shadow-soft active:scale-[0.98] transition-transform disabled:opacity-50 disabled:scale-100"
      >
        打卡
      </button>
    </div>
  );
}
