import { useEffect, useState } from "react";
import { Sparkles, Calendar } from "lucide-react";
import NumericKeypad from "@/components/NumericKeypad";
import RecordList from "@/components/RecordList";
import { useWeightStore } from "@/store/weightStore";
import { formatDate } from "@/utils/date";

export default function CheckIn() {
  const [input, setInput] = useState("");
  const [justSaved, setJustSaved] = useState(false);
  const { records, add, remove, getToday } = useWeightStore();

  const todayRecord = getToday();

  useEffect(() => {
    if (todayRecord) {
      setInput(todayRecord.weight.toString());
    } else {
      setInput("");
    }
  }, [todayRecord?.weight]);

  function handleSubmit() {
    const weight = parseFloat(input);
    if (Number.isNaN(weight) || weight <= 0) return;
    add(weight);
    setJustSaved(true);
    setTimeout(() => setJustSaved(false), 1500);
  }

  const recentRecords = [...records]
    .sort((a, b) => b.date.localeCompare(a.date))
    .slice(0, 7);

  return (
    <div className="flex flex-col gap-6 pb-nav">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-display font-bold text-olive flex items-center gap-2">
            体重打卡
            <Sparkles size={20} className="text-tangerine" />
          </h1>
          <p className="text-sm text-moss mt-1">每天记录，见证改变</p>
        </div>
        <div className="flex items-center gap-1.5 text-xs font-medium text-moss bg-white px-3 py-1.5 rounded-full shadow-card">
          <Calendar size={14} />
          {formatDate(new Date())}
        </div>
      </header>

      <section className="flex flex-col gap-4 p-5 bg-white rounded-3xl shadow-soft">
        <div className="flex flex-col items-center gap-1 py-4">
          <span className="text-sm text-moss font-medium">
            {todayRecord ? "今日已打卡" : "今日体重"}
          </span>
          <div className="flex items-baseline gap-2">
            <span className="text-6xl font-display font-bold text-olive tracking-tight">
              {input || "0"}
            </span>
            <span className="text-lg text-moss font-medium">kg</span>
          </div>
        </div>

        {justSaved && (
          <div className="text-center text-sm text-tangerine font-medium animate-pop">
            打卡成功 🎉
          </div>
        )}

        <NumericKeypad
          value={input}
          onChange={setInput}
          onSubmit={handleSubmit}
        />
      </section>

      <section className="flex flex-col gap-3">
        <h2 className="text-base font-display font-bold text-olive">最近记录</h2>
        <RecordList
          records={recentRecords}
          onDelete={remove}
          emptyText="还没有打卡记录，快来记录第一条吧"
        />
      </section>
    </div>
  );
}
