import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
} from "recharts";
import { ChartPoint } from "@/store/weightStore";

interface WeightChartProps {
  data: ChartPoint[];
}

export default function WeightChart({ data }: WeightChartProps) {
  if (data.length === 0) {
    return (
      <div className="flex items-center justify-center h-64 text-moss text-sm">
        暂无数据，快去打卡吧
      </div>
    );
  }

  const weights = data.map((d) => d.weight).filter((w) => w > 0);
  const min = Math.min(...weights);
  const max = Math.max(...weights);
  const padding = Math.max((max - min) * 0.2, 1);
  const yMin = Math.max(0, Math.floor(min - padding));
  const yMax = Math.ceil(max + padding);

  return (
    <div className="w-full h-64 animate-slideUp">
      <ResponsiveContainer width="100%" height="100%">
        <AreaChart data={data} margin={{ top: 8, right: 8, left: -20, bottom: 0 }}>
          <defs>
            <linearGradient id="weightGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#FF7A29" stopOpacity={0.25} />
              <stop offset="95%" stopColor="#FF7A29" stopOpacity={0} />
            </linearGradient>
          </defs>
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E3EBE8" />
          <XAxis
            dataKey="label"
            axisLine={false}
            tickLine={false}
            tick={{ fill: "#8DA399", fontSize: 11 }}
            interval="preserveStartEnd"
            minTickGap={24}
          />
          <YAxis
            domain={[yMin, yMax]}
            axisLine={false}
            tickLine={false}
            tick={{ fill: "#8DA399", fontSize: 11 }}
            tickFormatter={(v) => `${v}`}
          />
          <Tooltip
            contentStyle={{
              backgroundColor: "#2D3A26",
              border: "none",
              borderRadius: "0.75rem",
              color: "#FFFDF7",
              fontSize: "0.875rem",
            }}
            formatter={(value: number) => [`${value.toFixed(1)} kg`, "体重"]}
            labelStyle={{ color: "#FFFDF7", marginBottom: "0.25rem" }}
          />
          <Area
            type="monotone"
            dataKey="weight"
            stroke="#FF7A29"
            strokeWidth={3}
            fill="url(#weightGradient)"
            dot={{ r: 3, fill: "#FF7A29", strokeWidth: 0 }}
            activeDot={{ r: 5, stroke: "#FFFDF7", strokeWidth: 3 }}
          />
        </AreaChart>
      </ResponsiveContainer>
    </div>
  );
}
