import { create } from "zustand";
import {
  addClassRecord,
  ClassRecord,
  deleteClassRecord,
  getClassRecords,
  getClassRecordsByDate,
  getClassRecordsByMonth,
  updateClassRecord,
} from "@/utils/classStorage";

interface ClassState {
  records: ClassRecord[];
  refresh: () => void;
  add: (className: string, note: string, attended: boolean, date?: string) => void;
  update: (id: string, updates: Partial<Omit<ClassRecord, "id">>) => void;
  remove: (id: string) => void;
  getByDate: (date: string) => ClassRecord[];
  getByMonth: (year: number, month: number) => ClassRecord[];
}

export const useClassStore = create<ClassState>((set) => ({
  records: getClassRecords(),

  refresh: () => set({ records: getClassRecords() }),

  add: (className, note, attended, date) => {
    addClassRecord(className, note, attended, date);
    set({ records: getClassRecords() });
  },

  update: (id, updates) => {
    updateClassRecord(id, updates);
    set({ records: getClassRecords() });
  },

  remove: (id) => {
    deleteClassRecord(id);
    set({ records: getClassRecords() });
  },

  getByDate: (date) => getClassRecordsByDate(date),

  getByMonth: (year, month) => getClassRecordsByMonth(year, month),
}));
