import { useState, useMemo } from "react";
import { CalendarDays, BookOpen, CheckCircle2 } from "lucide-react";
import CalendarView from "@/components/CalendarView";
import CheckInSheet from "@/components/CheckInSheet";
import { useClassStore } from "@/store/classStore";
import { formatDate, getRelativeDateLabel } from "@/utils/date";

export default function Calendar() {
  const today = new Date();
  const [year, setYear] = useState(today.getFullYear());
  const [month, setMonth] = useState(today.getMonth());
  const [selectedDate, setSelectedDate] = useState(formatDate(today));
  const [sheetOpen, setSheetOpen] = useState(false);

  const { records, getByMonth } = useClassStore();

  const markedDates = useMemo(() => {
    const monthRecords = getByMonth(year, month);
    return new Set(monthRecords.map((r) => r.date));
  }, [records, year, month, getByMonth]);

  const monthRecords = useMemo(() => {
    return getByMonth(year, month)
      .sort((a, b) => b.date.localeCompare(a.date) || b.createdAt - a.createdAt);
  }, [records, year, month, getByMonth]);

  const attendedCount = monthRecords.filter((r) => r.attended).length;

  function handleMonthChange(y: number, m: number) {
    setYear(y);
    setMonth(m);
  }

  function handleSelectDate(date: string) {
    setSelectedDate(date);
    setSheetOpen(true);
  }

  return (
    <div className="flex flex-col gap-6 pb-nav">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-display font-bold text-olive flex items-center gap-2">
            上课打卡
            <CalendarDays size={22} className="text-tangerine" />
          </h1>
          <p className="text-sm text-moss mt-1">日历选择日期，记录每节课</p>
        </div>
        {monthRecords.length > 0 && (
          <div className="flex items-center gap-1.5 text-xs font-medium text-moss bg-white px-3 py-1.5 rounded-full shadow-card">
            <CheckCircle2 size={14} className="text-green-500" />
            {attendedCount}/{monthRecords.length} 节
          </div>
        )}
      </header>

      <CalendarView
        year={year}
        month={month}
        selectedDate={selectedDate}
        markedDates={markedDates}
        onMonthChange={handleMonthChange}
        onSelectDate={handleSelectDate}
      />

      <section className="flex flex-col gap-3">
        <h2 className="text-base font-display font-bold text-olive">
          本月记录
        </h2>
        {monthRecords.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 text-moss">
            <BookOpen size={32} className="mb-2 opacity-50" />
            <p className="text-sm">本月还没有上课打卡</p>
          </div>
        ) : (
          <div className="flex flex-col gap-2">
            {monthRecords.map((r, idx) => (
              <div
                key={r.id}
                className="flex items-center gap-3 p-4 bg-white rounded-2xl shadow-card animate-slideUp"
                style={{ animationDelay: `${idx * 0.03}s` }}
              >
                <div className="flex flex-col items-center justify-center w-12 shrink-0">
                  <span className="text-xl font-display font-bold text-olive">
                    {parseInt(r.date.slice(-2), 10)}
                  </span>
                  <span className="text-[10px] text-moss">
                    {r.date.slice(5, 7)}/{r.date.slice(8, 10)}
                  </span>
                </div>
                <div className="w-px h-10 bg-moss/20" />
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold text-olive truncate">{r.className}</p>
                  {r.note && (
                    <p className="text-xs text-moss mt-0.5 truncate">{r.note}</p>
                  )}
                </div>
                <span
                  className={`text-xs px-2 py-1 rounded-full font-medium ${
                    r.attended
                      ? "bg-green-50 text-green-600"
                      : "bg-tangerine-50 text-tangerine"
                  }`}
                >
                  {r.attended ? "已上课" : "未上课"}
                </span>
              </div>
            ))}
          </div>
        )}
      </section>

      {sheetOpen && (
        <CheckInSheet
          date={selectedDate}
          onClose={() => setSheetOpen(false)}
        />
      )}
    </div>
  );
}
