import { useMemo } from "react";
import { History } from "lucide-react";
import RecordList from "@/components/RecordList";
import { useWeightStore } from "@/store/weightStore";

export default function Records() {
  const { records, remove } = useWeightStore();

  const allRecords = useMemo(
    () => [...records].sort((a, b) => b.date.localeCompare(a.date)),
    [records]
  );

  return (
    <div className="flex flex-col gap-6 pb-nav">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-display font-bold text-olive flex items-center gap-2">
            全部记录
            <History size={22} className="text-tangerine" />
          </h1>
          <p className="text-sm text-moss mt-1">共 {allRecords.length} 条打卡记录</p>
        </div>
      </header>

      <section className="flex flex-col gap-3">
        <RecordList
          records={allRecords}
          onDelete={remove}
          emptyText="暂无打卡记录"
        />
      </section>
    </div>
  );
}
