import { create } from "zustand";
import {
  addRecord,
  deleteRecord,
  getLatestRecord,
  getRecordByDate,
  getRecords,
  WeightRecord,
} from "@/utils/storage";
import { formatDate, getDateRange } from "@/utils/date";

export type Range = "week" | "month" | "quarter";

export interface ChartPoint {
  date: string;
  label: string;
  weight: number;
}

export interface StatsSummary {
  average: number;
  max: number;
  min: number;
  change: number;
  count: number;
}

interface WeightState {
  records: WeightRecord[];
  refresh: () => void;
  add: (weight: number, date?: string) => void;
  remove: (id: string) => void;
  getLatest: () => WeightRecord | null;
  getToday: () => WeightRecord | null;
  getChartData: (range: Range) => ChartPoint[];
  getSummary: (range: Range) => StatsSummary | null;
}

function getRangeDays(range: Range): number {
  switch (range) {
    case "week":
      return 6;
    case "month":
      return 29;
    case "quarter":
      return 89;
  }
}

function buildDailyMap(records: WeightRecord[]): Map<string, WeightRecord> {
  const map = new Map<string, WeightRecord>();
  for (const record of records) {
    const existing = map.get(record.date);
    if (!existing || record.createdAt > existing.createdAt) {
      map.set(record.date, record);
    }
  }
  return map;
}

function formatChartLabel(dateStr: string, range: Range): string {
  const date = new Date(dateStr);
  const month = date.getMonth() + 1;
  const day = date.getDate();
  if (range === "week") return `${month}/${day}`;
  if (range === "month") return `${month}/${day}`;
  return `${month}/${day}`;
}

export const useWeightStore = create<WeightState>((set, get) => ({
  records: getRecords(),

  refresh: () => set({ records: getRecords() }),

  add: (weight, date) => {
    addRecord(weight, date);
    set({ records: getRecords() });
  },

  remove: (id) => {
    deleteRecord(id);
    set({ records: getRecords() });
  },

  getLatest: () => getLatestRecord(),

  getToday: () => getRecordByDate(formatDate(new Date())),

  getChartData: (range) => {
    const days = getRangeDays(range);
    const dates = getDateRange(days);
    const dailyMap = buildDailyMap(get().records);

    if (range === "quarter") {
      const points: ChartPoint[] = [];
      for (let i = 0; i < dates.length; i += 7) {
        const chunk = dates.slice(i, i + 7);
        const values = chunk
          .map((d) => dailyMap.get(d)?.weight)
          .filter((v): v is number => v !== undefined);
        if (values.length > 0) {
          const avg = values.reduce((a, b) => a + b, 0) / values.length;
          const middleDate = chunk[Math.floor(chunk.length / 2)];
          points.push({
            date: middleDate,
            label: formatChartLabel(middleDate, range),
            weight: Math.round(avg * 10) / 10,
          });
        }
      }
      return points;
    }

    return dates.map((date) => ({
      date,
      label: formatChartLabel(date, range),
      weight: dailyMap.get(date)?.weight ?? 0,
    }));
  },

  getSummary: (range) => {
    const data = get()
      .getChartData(range)
      .filter((p) => p.weight > 0);
    if (data.length === 0) return null;

    const weights = data.map((p) => p.weight);
    const average = Math.round((weights.reduce((a, b) => a + b, 0) / weights.length) * 10) / 10;
    const max = Math.max(...weights);
    const min = Math.min(...weights);
    const change = Math.round((weights[weights.length - 1] - weights[0]) * 10) / 10;

    return { average, max, min, change, count: weights.length };
  },
}));
