import { Link, useLocation } from "react-router-dom";
import { CalendarCheck, TrendingUp, ClipboardList, CalendarDays } from "lucide-react";
import { cn } from "@/lib/utils";

const tabs = [
  { path: "/", label: "体重", icon: CalendarCheck },
  { path: "/calendar", label: "上课", icon: CalendarDays },
  { path: "/stats", label: "统计", icon: TrendingUp },
  { path: "/records", label: "记录", icon: ClipboardList },
];

export default function BottomNav() {
  const location = useLocation();

  return (
    <nav className="fixed bottom-0 left-0 right-0 z-50 bg-cream/90 backdrop-blur-md border-t border-moss/20 safe-bottom">
      <div className="max-w-md mx-auto flex items-center justify-around h-16">
        {tabs.map((tab) => {
          const isActive = location.pathname === tab.path;
          const Icon = tab.icon;
          return (
            <Link
              key={tab.path}
              to={tab.path}
              className={cn(
                "flex flex-col items-center justify-center w-full h-full gap-1 transition-colors duration-200",
                isActive ? "text-tangerine" : "text-moss"
              )}
            >
              <div
                className={cn(
                  "flex items-center justify-center w-10 h-10 rounded-full transition-all duration-200",
                  isActive ? "bg-tangerine-50" : "bg-transparent"
                )}
              >
                <Icon size={22} strokeWidth={isActive ? 2.5 : 2} />
              </div>
              <span className="text-[10px] font-medium">{tab.label}</span>
            </Link>
          );
        })}
      </div>
    </nav>
  );
}
