import { formatDate } from "@/utils/date";

const STORAGE_KEY = "weight_records";

export interface WeightRecord {
  id: string;
  date: string;
  weight: number;
  createdAt: number;
}

export function getRecords(): WeightRecord[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as WeightRecord[];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function saveRecords(records: WeightRecord[]): void {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
}

export function addRecord(weight: number, date = formatDate(new Date())): WeightRecord {
  const records = getRecords();
  const existingIndex = records.findIndex((r) => r.date === date);

  const newRecord: WeightRecord = {
    id: existingIndex >= 0 ? records[existingIndex].id : `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    date,
    weight: Math.round(weight * 10) / 10,
    createdAt: Date.now(),
  };

  if (existingIndex >= 0) {
    records[existingIndex] = newRecord;
  } else {
    records.push(newRecord);
  }

  records.sort((a, b) => a.date.localeCompare(b.date));
  saveRecords(records);
  return newRecord;
}

export function deleteRecord(id: string): void {
  const records = getRecords().filter((r) => r.id !== id);
  saveRecords(records);
}

export function getLatestRecord(): WeightRecord | null {
  const records = getRecords();
  if (records.length === 0) return null;
  return records.reduce((latest, record) =>
    record.date > latest.date ? record : latest
  );
}

export function getRecordByDate(date: string): WeightRecord | null {
  return getRecords().find((r) => r.date === date) || null;
}
