import { formatDate } from "@/utils/date";

const STORAGE_KEY = "class_records";

export interface ClassRecord {
  id: string;
  date: string; // YYYY-MM-DD
  className: string; // 课程名称
  note: string; // 备注
  attended: boolean; // 是否已上课
  createdAt: number;
}

export function getClassRecords(): ClassRecord[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as ClassRecord[];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function saveClassRecords(records: ClassRecord[]): void {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
}

export function addClassRecord(
  className: string,
  note: string,
  attended: boolean,
  date = formatDate(new Date())
): ClassRecord {
  const records = getClassRecords();
  const newRecord: ClassRecord = {
    id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    date,
    className,
    note,
    attended,
    createdAt: Date.now(),
  };
  records.push(newRecord);
  records.sort((a, b) => a.date.localeCompare(b.date));
  saveClassRecords(records);
  return newRecord;
}

export function updateClassRecord(id: string, updates: Partial<Omit<ClassRecord, "id">>): void {
  const records = getClassRecords();
  const index = records.findIndex((r) => r.id === id);
  if (index >= 0) {
    records[index] = { ...records[index], ...updates };
    saveClassRecords(records);
  }
}

export function deleteClassRecord(id: string): void {
  const records = getClassRecords().filter((r) => r.id !== id);
  saveClassRecords(records);
}

export function getClassRecordsByDate(date: string): ClassRecord[] {
  return getClassRecords()
    .filter((r) => r.date === date)
    .sort((a, b) => b.createdAt - a.createdAt);
}

export function getClassRecordsByMonth(year: number, month: number): ClassRecord[] {
  const prefix = `${year}-${String(month + 1).padStart(2, "0")}`;
  return getClassRecords().filter((r) => r.date.startsWith(prefix));
}
