import { useState } from "react";
import { X, Check, BookOpen, FileText, Trash2 } from "lucide-react";
import { useClassStore } from "@/store/classStore";
import { getRelativeDateLabel } from "@/utils/date";
import { cn } from "@/lib/utils";

interface CheckInSheetProps {
  date: string;
  onClose: () => void;
}

export default function CheckInSheet({ date, onClose }: CheckInSheetProps) {
  const { getByDate, add, remove } = useClassStore();
  const [className, setClassName] = useState("");
  const [note, setNote] = useState("");
  const [attended, setAttended] = useState(true);

  const records = getByDate(date);

  function handleAdd() {
    if (!className.trim()) return;
    add(className.trim(), note.trim(), attended, date);
    setClassName("");
    setNote("");
    setAttended(true);
  }

  return (
    <>
      <div
        className="fixed inset-0 bg-olive/40 backdrop-blur-sm z-40 animate-[fadeIn_0.2s_ease-out]"
        onClick={onClose}
      />
      <div className="fixed bottom-20 left-4 right-4 z-50 max-w-md mx-auto bg-cream rounded-3xl shadow-soft safe-bottom animate-slideUp">
        <div className="flex items-center justify-between p-5 pb-3">
          <div>
            <h3 className="font-display font-bold text-olive text-lg">
              {date.slice(5)} · {getRelativeDateLabel(date)}
            </h3>
            <p className="text-xs text-moss mt-0.5">上课打卡</p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="flex items-center justify-center w-9 h-9 rounded-full bg-moss-100 text-moss active:scale-90"
            aria-label="关闭"
          >
            <X size={18} />
          </button>
        </div>

        <div className="px-5 pb-3 max-h-[40vh] overflow-y-auto">
          {records.length === 0 ? (
            <p className="text-center text-sm text-moss py-6">暂无打卡记录</p>
          ) : (
            <div className="flex flex-col gap-2">
              {records.map((r) => (
                <div
                  key={r.id}
                  className="flex items-start gap-3 p-3 bg-white rounded-2xl shadow-card"
                >
                  <div
                    className={cn(
                      "flex items-center justify-center w-8 h-8 rounded-full shrink-0",
                      r.attended ? "bg-green-50 text-green-600" : "bg-tangerine-50 text-tangerine"
                    )}
                  >
                    <Check size={16} strokeWidth={3} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold text-olive truncate">{r.className}</p>
                    {r.note && <p className="text-xs text-moss mt-0.5 break-words">{r.note}</p>}
                  </div>
                  <button
                    type="button"
                    onClick={() => remove(r.id)}
                    className="flex items-center justify-center w-8 h-8 rounded-full text-red-400 active:scale-90"
                    aria-label="删除"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="p-5 pt-2 border-t border-moss/10">
          <div className="flex flex-col gap-3">
            <div className="flex items-center gap-2 p-3 bg-white rounded-2xl shadow-card">
              <BookOpen size={18} className="text-moss shrink-0" />
              <input
                type="text"
                value={className}
                onChange={(e) => setClassName(e.target.value)}
                placeholder="课程名称（如：高数、英语）"
                maxLength={20}
                className="flex-1 bg-transparent outline-none text-sm text-olive placeholder:text-moss/60"
              />
            </div>

            <div className="flex items-start gap-2 p-3 bg-white rounded-2xl shadow-card">
              <FileText size={18} className="text-moss shrink-0 mt-0.5" />
              <textarea
                value={note}
                onChange={(e) => setNote(e.target.value)}
                placeholder="备注信息（可选）"
                maxLength={100}
                rows={2}
                className="flex-1 bg-transparent outline-none text-sm text-olive placeholder:text-moss/60 resize-none"
              />
            </div>

            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => setAttended(!attended)}
                className={cn(
                  "flex-1 py-2.5 rounded-xl text-sm font-medium transition-colors",
                  attended
                    ? "bg-green-50 text-green-600 border border-green-200"
                    : "bg-moss-100 text-moss"
                )}
              >
                {attended ? "✓ 已上课" : "未上课"}
              </button>
              <button
                type="button"
                onClick={handleAdd}
                disabled={!className.trim()}
                className="flex-1 py-2.5 rounded-xl bg-tangerine text-white text-sm font-semibold shadow-soft active:scale-[0.98] transition-transform disabled:opacity-50"
              >
                打卡
              </button>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
