import { useMemo } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { formatDate } from "@/utils/date";
import { cn } from "@/lib/utils";

interface CalendarViewProps {
  year: number;
  month: number;
  selectedDate: string;
  markedDates: Set<string>;
  onMonthChange: (year: number, month: number) => void;
  onSelectDate: (date: string) => void;
}

const WEEK_DAYS = ["日", "一", "二", "三", "四", "五", "六"];
const MONTH_NAMES = [
  "一月", "二月", "三月", "四月", "五月", "六月",
  "七月", "八月", "九月", "十月", "十一月", "十二月",
];

export default function CalendarView({
  year,
  month,
  selectedDate,
  markedDates,
  onMonthChange,
  onSelectDate,
}: CalendarViewProps) {
  const today = formatDate(new Date());

  const days = useMemo(() => {
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const startWeekday = firstDay.getDay();
    const totalDays = lastDay.getDate();

    const cells: (string | null)[] = [];
    for (let i = 0; i < startWeekday; i++) cells.push(null);
    for (let d = 1; d <= totalDays; d++) {
      cells.push(formatDate(new Date(year, month, d)));
    }
    const remaining = (7 - (cells.length % 7)) % 7;
    for (let i = 0; i < remaining; i++) cells.push(null);
    return cells;
  }, [year, month]);

  function prevMonth() {
    if (month === 0) onMonthChange(year - 1, 11);
    else onMonthChange(year, month - 1);
  }

  function nextMonth() {
    if (month === 11) onMonthChange(year + 1, 0);
    else onMonthChange(year, month + 1);
  }

  return (
    <div className="bg-white rounded-3xl shadow-soft p-4">
      <div className="flex items-center justify-between mb-4">
        <button
          type="button"
          onClick={prevMonth}
          className="flex items-center justify-center w-9 h-9 rounded-full active:bg-tangerine-50 text-moss"
          aria-label="上个月"
        >
          <ChevronLeft size={20} />
        </button>
        <h2 className="font-display font-bold text-olive text-lg">
          {year}年{MONTH_NAMES[month]}
        </h2>
        <button
          type="button"
          onClick={nextMonth}
          className="flex items-center justify-center w-9 h-9 rounded-full active:bg-tangerine-50 text-moss"
          aria-label="下个月"
        >
          <ChevronRight size={20} />
        </button>
      </div>

      <div className="grid grid-cols-7 mb-2">
        {WEEK_DAYS.map((d) => (
          <div key={d} className="text-center text-xs text-moss font-medium py-2">
            {d}
          </div>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-1">
        {days.map((dateStr, idx) => {
          if (!dateStr) {
            return <div key={`empty-${idx}`} className="aspect-square" />;
          }
          const day = parseInt(dateStr.slice(-2), 10);
          const isToday = dateStr === today;
          const isSelected = dateStr === selectedDate;
          const isMarked = markedDates.has(dateStr);

          return (
            <button
              key={dateStr}
              type="button"
              onClick={() => onSelectDate(dateStr)}
              className={cn(
                "relative aspect-square flex flex-col items-center justify-center rounded-xl text-sm font-medium transition-all duration-150",
                isSelected
                  ? "bg-tangerine text-white shadow-soft"
                  : isToday
                  ? "bg-tangerine-50 text-tangerine"
                  : "text-olive active:bg-tangerine-50"
              )}
            >
              <span>{day}</span>
              {isMarked && (
                <span
                  className={cn(
                    "absolute bottom-1 w-1 h-1 rounded-full",
                    isSelected ? "bg-white" : "bg-tangerine"
                  )}
                />
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}
