import { useState, useMemo } from "react";
import { BarChart3 } from "lucide-react";
import { Range, useWeightStore } from "@/store/weightStore";
import WeightChart from "@/components/WeightChart";
import SummaryCards from "@/components/SummaryCards";
import { cn } from "@/lib/utils";

const ranges: { key: Range; label: string }[] = [
  { key: "week", label: "周" },
  { key: "month", label: "月" },
  { key: "quarter", label: "季" },
];

export default function Stats() {
  const [range, setRange] = useState<Range>("week");
  const { getChartData, getSummary } = useWeightStore();

  const data = useMemo(() => getChartData(range), [range, getChartData]);
  const summary = useMemo(() => getSummary(range), [range, getSummary]);

  return (
    <div className="flex flex-col gap-6 pb-nav">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-display font-bold text-olive flex items-center gap-2">
            趋势统计
            <BarChart3 size={22} className="text-tangerine" />
          </h1>
          <p className="text-sm text-moss mt-1">看看你的体重变化趋势</p>
        </div>
      </header>

      <div className="p-1 bg-white rounded-2xl shadow-card flex">
        {ranges.map((item) => (
          <button
            key={item.key}
            type="button"
            onClick={() => setRange(item.key)}
            className={cn(
              "flex-1 py-2 text-sm font-semibold rounded-xl transition-all duration-200",
              range === item.key
                ? "bg-tangerine text-white shadow-sm"
                : "text-moss hover:bg-tangerine-50"
            )}
          >
            {item.label}
          </button>
        ))}
      </div>

      <section className="p-4 bg-white rounded-3xl shadow-soft">
        <h2 className="text-base font-display font-bold text-olive mb-2">
          {ranges.find((r) => r.key === range)?.label}趋势
        </h2>
        <WeightChart data={data} />
      </section>

      <section className="flex flex-col gap-3">
        <h2 className="text-base font-display font-bold text-olive">数据摘要</h2>
        <SummaryCards summary={summary} />
      </section>
    </div>
  );
}
