import { Trash2 } from "lucide-react";
import { WeightRecord } from "@/utils/storage";
import { getRelativeDateLabel } from "@/utils/date";

interface RecordListProps {
  records: WeightRecord[];
  onDelete: (id: string) => void;
  emptyText?: string;
}

export default function RecordList({
  records,
  onDelete,
  emptyText = "暂无记录",
}: RecordListProps) {
  if (records.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 text-moss">
        <p className="text-sm">{emptyText}</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-3">
      {records.map((record, index) => (
        <div
          key={record.id}
          className="group flex items-center justify-between p-4 bg-white rounded-2xl shadow-card animate-slideUp"
          style={{ animationDelay: `${index * 0.05}s` }}
        >
          <div className="flex flex-col gap-0.5">
            <span className="text-xs text-moss font-medium">
              {record.date} · {getRelativeDateLabel(record.date)}
            </span>
            <span className="text-2xl font-display font-bold text-olive">
              {record.weight.toFixed(1)}
              <span className="text-sm font-body font-medium text-moss ml-1">kg</span>
            </span>
          </div>
          <button
            type="button"
            onClick={() => onDelete(record.id)}
            className="flex items-center justify-center w-10 h-10 rounded-full bg-red-50 text-red-500 active:scale-90 transition-transform"
            aria-label="删除记录"
          >
            <Trash2 size={18} />
          </button>
        </div>
      ))}
    </div>
  );
}
