export function formatDate(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

export function parseDate(dateStr: string): Date {
  const [y, m, d] = dateStr.split("-").map(Number);
  return new Date(y, m - 1, d);
}

export function getRelativeDateLabel(dateStr: string): string {
  const today = formatDate(new Date());
  if (dateStr === today) return "今天";

  const yesterday = formatDate(new Date(Date.now() - 86400000));
  if (dateStr === yesterday) return "昨天";

  const date = parseDate(dateStr);
  const now = new Date();
  const diffDays = Math.floor(
    (new Date(today).getTime() - date.getTime()) / 86400000
  );
  if (diffDays > 0 && diffDays <= 7) return `${diffDays} 天前`;

  return `${date.getMonth() + 1}月${date.getDate()}日`;
}

export function getPastDate(days: number): Date {
  const date = new Date();
  date.setDate(date.getDate() - days);
  date.setHours(0, 0, 0, 0);
  return date;
}

export function getDateRange(startDaysAgo: number): string[] {
  const dates: string[] = [];
  for (let i = startDaysAgo; i >= 0; i--) {
    dates.push(formatDate(getPastDate(i)));
  }
  return dates;
}
